// Request
public record GetProductQuery(int Id) : IRequest<Product?>;

// Handler
public class GetProductHandler : IRequestHandler<GetProductQuery, Product?>
{
    private readonly IRepository<Product> _repo;

    public GetProductHandler(IRepository<Product> repo)
    {
        _repo = repo;
    }

    public async Task<Product?> Handle(GetProductQuery request, CancellationToken ct)
    {
        return await _repo.GetByIdAsync(request.Id);
    }
}

// Usage
var product = await _mediator.Send(new GetProductQuery(42));
